for db_path in ['question_bank.db', 'instance/question_bank.db']:
    conn = sqlite3.connect(db_path)
    c = conn.cursor()
    
    # Delete existing short & cq for this chapter if any
    c.execute("DELETE FROM questions WHERE chapter_id = ? AND question_type IN ('short', 'cq')", (CHAPTER_ID,))
    
    for sq in short_qs:
        c.execute("""
            INSERT INTO questions (
                class_id, subject_id, chapter_id, question_type, difficulty, marks,
                short_question, short_answer
            ) VALUES (?, ?, ?, 'short', 'medium', 2.0, ?, ?)
        """, (CLASS_ID, SUBJECT_ID, CHAPTER_ID, sq["q"], sq["a"]))
        
    for cq in cqs:
        c.execute("""
            INSERT INTO questions (
                class_id, subject_id, chapter_id, question_type, difficulty, marks,
                cq_stem, cq_sub_ka, cq_sub_kha, cq_sub_ga, cq_sub_gha, cq_solution
            ) VALUES (?, ?, ?, 'cq', 'medium', 10.0, ?, ?, ?, ?, ?, ?)
        """, (CLASS_ID, SUBJECT_ID, CHAPTER_ID, cq["stem"], cq["ka"], cq["kha"], cq["ga"], cq["gha"], cq["solution"]))
        
    conn.commit()
    conn.close()
    print(f"Successfully inserted into {db_path}!")
